import { useMemo, useState } from "react";
import { ArrowLeft, BarChart3, BookOpen, CircleAlert, Download, Filter, LockKeyhole, Radar, ShieldAlert, Sparkles } from "lucide-react";
import { trpc } from "@/lib/trpc";
import { usePwaStatus } from "@/pwa/PwaStatus";
import { useAuth } from "@/_core/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";

const STATUS_ORDER = ["QUALIFIED", "POTENTIAL", "WATCH", "NO TRADE", "DATA UNAVAILABLE"] as const;
type Status = (typeof STATUS_ORDER)[number];
type Strategy = "SCALP" | "SWING";
type StatusFilter = "ALL" | Status;
type StrategyFilter = "ALL" | Strategy;
type DirectionFilter = "ALL" | "LONG" | "SHORT";
type RegimeFilter = "ALL" | "RISK ON" | "SELECTIVE" | "NEUTRAL" | "RISK OFF" | "UNAVAILABLE";
type HealthFilter = "ALL" | "HEALTHY" | "WARNING" | "REVERSAL RISK" | "INVALIDATED" | "UNKNOWN";
type TimeframeFilter = "ALL" | "15M" | "1H" | "4H" | "1D";
type JournalFilter = "ALL" | string;

type DiscoveryItem = {
  assetId: string;
  symbol: string;
  status: Status;
  direction: "LONG" | "SHORT" | "NO TRADE";
  opportunityScore: number | null;
  adaptive?: { status?: string; quality?: { score: number | null; confidence: string }; warnings?: string[] };
  setupReadiness?: { score: number | null };
  tradeReadiness?: string;
  provider?: string | null;
  dataTimestamp: number | null;
  regime?: { classification: string | null; restricted: boolean };
  timeframes?: { execution?: string; confirmation?: string; context?: string };
  exactReason?: string;
  missingEvidence?: string[];
  confirmationRequirements?: string[];
  sourcePlan?: {
    entryZone: { preferred: number; reason: string } | null;
    stop: { price: number; reason: string } | null;
    targets: Array<{ label: string; price: number; reason: string }>;
    rewardRisk: number | null;
  };
};

type DiscoveryResponse = {
  generatedAt?: number;
  marketRegime?: { classification: string; score: number } | null;
  discovery?: { items: DiscoveryItem[]; summary: { evaluated: number; qualified: number; potential: number; watch: number; noTrade: number; dataUnavailable: number; restrictedByRiskOff: number } };
};

type WorkspaceItem = DiscoveryItem & { strategy: Strategy; sector: string };
type Trial = {
  id: number;
  assetId: string;
  strategy: string;
  timeframe: string;
  direction: string;
  mode: string;
  status: string;
  entryPrice?: number;
  stopPrice?: number;
  target1?: number | null;
  target2?: number | null;
  target3?: number | null;
  positionSize?: number;
  riskPercent?: number;
  setupQuality?: number | null;
  realizedPnl: number | null;
  currentPnl: number | null;
  createdAt: Date | string;
  completedAt?: Date | string | null;
  provider?: string | null;
  freshness?: string | null;
  provenance?: unknown;
  immutablePlanSnapshot: unknown;
  currentSnapshot?: unknown;
};
type CompareRow = { label: string; trials: number; active?: number; completed: number; wins: number; losses?: number; pnl: number; winRate?: number | null; averageR?: number | null; sampleQuality?: string };
type CoverageRow = { assetId: string; registrySector?: string | null; sectorClassificationStatus?: string | null; sectorStatus?: string | null; dataQualityStatus?: string | null; timeframes?: Record<string, { status?: string; expected?: number; observed?: number; missing?: number; coveragePercent?: number; qualityRating?: string }> };

type PerformancePayload = { totalTrials?: number; active?: number; completed?: number; wins?: number; losses?: number; winRate?: number | null; averageR?: number | null; netPnl?: number; currentEquity?: number; maximumDrawdown?: number; sampleLabel?: string; insufficientSample?: boolean; byStrategy?: unknown[]; byTimeframe?: unknown[]; byDirection?: unknown[] };
type EligibilityPayload = { generatedAt?: number; enabled?: boolean; eligibleCount?: number; activeCount?: number; counts?: { ELIGIBLE?: number; NOT_ELIGIBLE?: number; DATA_UNAVAILABLE?: number; REQUIRES_CONFIRMATION?: number; DUPLICATE?: number }; rows?: Array<{ symbol: string; strategy: string; timeframe: string; direction: string; state: string; reason: string; setupQuality: number | null; rewardRisk: number | null; regime: string | null }> };

const money = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 2 });
const date = (value: Date | string | number | null | undefined) => value ? new Date(value).toLocaleString() : "UNAVAILABLE";
const number = (value: number | null | undefined, digits = 2) => value == null || !Number.isFinite(value) ? "UNAVAILABLE" : value.toFixed(digits);
const sampleQuality = (completed: number) => completed <= 0 ? "NO DATA" : completed < 5 ? "VERY SMALL" : completed < 50 ? "SMALL" : completed < 500 ? "DEVELOPING" : "MEANINGFUL";
const safeJson = (value: unknown) => { try { return JSON.stringify(value ?? "UNAVAILABLE"); } catch { return "UNAVAILABLE"; } };

function healthFor(item: WorkspaceItem): HealthFilter {
  if (item.status === "QUALIFIED") return "HEALTHY";
  if (item.status === "POTENTIAL" || item.status === "WATCH") return "WARNING";
  if (item.status === "NO TRADE") return "INVALIDATED";
  return "UNKNOWN";
}

function timeframeFor(item: WorkspaceItem) { return String(item.timeframes?.execution ?? "UNAVAILABLE").toUpperCase(); }
function snapshotObject(value: unknown): Record<string, any> { return value && typeof value === "object" ? value as Record<string, any> : {}; }
function qualificationFor(trial: Trial) { const snapshot = snapshotObject(trial.immutablePlanSnapshot); return typeof snapshot.adaptiveQualification?.status === "string" ? snapshot.adaptiveQualification.status : typeof snapshot.qualification?.status === "string" ? snapshot.qualification.status : "UNAVAILABLE"; }
function regimeFor(trial: Trial) { const snapshot = snapshotObject(trial.immutablePlanSnapshot); return typeof snapshot.regime === "string" ? snapshot.regime : typeof snapshot.marketRegime === "string" ? snapshot.marketRegime : "UNAVAILABLE"; }
function isTerminal(trial: Trial) { return ["STOPPED", "CLOSED", "COMPLETED", "EXPIRED", "INVALIDATED"].includes(trial.status); }
function trialPnl(trial: Trial) { return Number(isTerminal(trial) ? trial.realizedPnl ?? 0 : trial.currentPnl ?? 0); }
function trialR(trial: Trial) { const riskAmount = Number((trial.entryPrice ?? 0) * (trial.positionSize ?? 0) * (trial.riskPercent ?? 0) / 100); return riskAmount > 0 ? Number(trial.realizedPnl ?? 0) / riskAmount : null; }
function resultFor(trial: Trial) { if (!isTerminal(trial)) return "ACTIVE"; const pnl = Number(trial.realizedPnl ?? 0); return pnl > 0 ? "WIN" : pnl < 0 ? "LOSS" : "BREAKEVEN"; }
function groupTrials(trials: Trial[], labelFor: (trial: Trial) => string): CompareRow[] {
  const labels = Array.from(new Set(trials.map(labelFor))).sort((left, right) => left.localeCompare(right));
  return labels.map(label => {
    const group = trials.filter(trial => labelFor(trial) === label);
    const completed = group.filter(isTerminal);
    const wins = completed.filter(trial => Number(trial.realizedPnl ?? 0) > 0).length;
    const rValues = completed.map(trialR).filter((value): value is number => value != null && Number.isFinite(value));
    return { label, trials: group.length, active: group.length - completed.length, completed: completed.length, wins, losses: completed.filter(trial => Number(trial.realizedPnl ?? 0) < 0).length, pnl: group.reduce((sum, trial) => sum + trialPnl(trial), 0), winRate: completed.length >= 5 ? wins / completed.length * 100 : null, averageR: completed.length >= 5 && rValues.length ? rValues.reduce((sum, value) => sum + value, 0) / rValues.length : null, sampleQuality: sampleQuality(completed.length) };
  });
}
function serverRows(data: unknown, key: string, labelFor?: (value: string) => string): CompareRow[] {
  const rows = ((data as PerformancePayload | undefined)?.[key as keyof PerformancePayload] ?? []) as Array<Record<string, any>>;
  return rows.map(row => { const raw = String(row.strategy ?? row.timeframe ?? row.direction ?? row.mode ?? row.assetId ?? "UNAVAILABLE"); const label = labelFor ? labelFor(raw) : raw; return { label, trials: Number(row.trials ?? 0), active: Number(row.active ?? 0), completed: Number(row.completed ?? 0), wins: Number(row.wins ?? 0), losses: Number(row.losses ?? 0), pnl: Number(row.pnl ?? 0), winRate: row.winRate == null ? null : Number(row.winRate), averageR: row.averageR == null ? null : Number(row.averageR), sampleQuality: sampleQuality(Number(row.completed ?? 0)) }; });
}
function csvEscape(value: unknown) { const text = value == null ? "" : typeof value === "string" ? value : safeJson(value); return /[",\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text; }
function toCsv(rows: Array<Record<string, unknown>>) { if (!rows.length) return ""; const columns = Object.keys(rows[0]); return `${columns.join(",")}\n${rows.map(row => columns.map(column => csvEscape(row[column])).join(",")).join("\n")}`; }
function downloadText(filename: string, payload: string, contentType: string) { const blob = new Blob([payload], { type: contentType }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = filename; anchor.click(); URL.revokeObjectURL(url); }

export function TradingIntelligenceWorkspace({ onBack, onOpenAutoPaper, onInspectAsset }: { onBack: () => void; onOpenAutoPaper: () => void; onInspectAsset?: (assetId: string) => void }) {
  const { online } = usePwaStatus();
  const { isAuthenticated } = useAuth();
  const privateEnabled = online && isAuthenticated;
  const [status, setStatus] = useState<StatusFilter>("ALL");
  const [strategy, setStrategy] = useState<StrategyFilter>("ALL");
  const [direction, setDirection] = useState<DirectionFilter>("ALL");
  const [regime, setRegime] = useState<RegimeFilter>("ALL");
  const [health, setHealth] = useState<HealthFilter>("ALL");
  const [timeframe, setTimeframe] = useState<TimeframeFilter>("ALL");
  const [journalStrategy, setJournalStrategy] = useState<JournalFilter>("ALL");
  const [journalTimeframe, setJournalTimeframe] = useState<JournalFilter>("ALL");
  const [journalStatus, setJournalStatus] = useState<JournalFilter>("ALL");
  const [journalDirection, setJournalDirection] = useState<JournalFilter>("ALL");
  const [journalRegime, setJournalRegime] = useState<JournalFilter>("ALL");
  const [journalResult, setJournalResult] = useState<JournalFilter>("ALL");

  const scalpQuery = trpc.crypto.tradeSetups.useQuery({ mode: "SCALP" }, { enabled: online, staleTime: 30_000, refetchOnWindowFocus: false });
  const swingQuery = trpc.crypto.tradeSetups.useQuery({ mode: "SWING" }, { enabled: online, staleTime: 30_000, refetchOnWindowFocus: false });
  const scannerQuery = trpc.crypto.scanner.useQuery(undefined, { enabled: online, staleTime: 45_000, refetchOnWindowFocus: false });
  const performanceQuery = trpc.crypto.autoPaperPerformance.useQuery(undefined, { enabled: privateEnabled, staleTime: 20_000, refetchOnWindowFocus: false });
  const eligibilityQuery = trpc.crypto.autoPaperEligibilitySummary.useQuery(undefined, { enabled: privateEnabled, staleTime: 30_000, refetchOnWindowFocus: false });
  const historyQuery = trpc.crypto.autoPaperHistory.useQuery(undefined, { enabled: privateEnabled, staleTime: 20_000, refetchOnWindowFocus: false });
  const qualifiedQuery = trpc.crypto.autoPaperPerformance.useQuery({ qualification: "QUALIFIED" }, { enabled: privateEnabled, staleTime: 20_000, refetchOnWindowFocus: false });
  const potentialQuery = trpc.crypto.autoPaperPerformance.useQuery({ qualification: "POTENTIAL" }, { enabled: privateEnabled, staleTime: 20_000, refetchOnWindowFocus: false });
  const watchQuery = trpc.crypto.autoPaperPerformance.useQuery({ qualification: "WATCH" }, { enabled: privateEnabled, staleTime: 20_000, refetchOnWindowFocus: false });
  const riskOnQuery = trpc.crypto.autoPaperPerformance.useQuery({ regime: "RISK ON" }, { enabled: privateEnabled, staleTime: 20_000, refetchOnWindowFocus: false });
  const neutralQuery = trpc.crypto.autoPaperPerformance.useQuery({ regime: "NEUTRAL" }, { enabled: privateEnabled, staleTime: 20_000, refetchOnWindowFocus: false });
  const riskOffQuery = trpc.crypto.autoPaperPerformance.useQuery({ regime: "RISK OFF" }, { enabled: privateEnabled, staleTime: 20_000, refetchOnWindowFocus: false });
  const datasetsQuery = trpc.crypto.historicalDatasets.useQuery(undefined, { enabled: privateEnabled, staleTime: 60_000, refetchOnWindowFocus: false });
  const datasetId = Number(((datasetsQuery.data as any)?.[0]?.id ?? 0));
  const coverageInput = useMemo(() => ({ datasetId }), [datasetId]);
  const coverageQuery = trpc.crypto.marketCoverageMatrix.useQuery(coverageInput, { enabled: privateEnabled && datasetId > 0, staleTime: 60_000, refetchOnWindowFocus: false });

  const sectorsByAsset = useMemo(() => {
    const rows = ((scannerQuery.data as any)?.rows ?? []) as Array<{ asset?: { id?: string; sector?: string } }>;
    return new Map(rows.filter(row => row.asset?.id).map(row => [row.asset!.id!, row.asset?.sector?.trim() || "UNKNOWN / UNCLASSIFIED"]));
  }, [scannerQuery.data]);
  const items = useMemo(() => {
    const sources: Array<[Strategy, unknown]> = [["SCALP", scalpQuery.data], ["SWING", swingQuery.data]];
    return sources.flatMap(([sourceStrategy, raw]) => { const response = raw as DiscoveryResponse | undefined; return (response?.discovery?.items ?? []).map(item => ({ ...item, strategy: sourceStrategy, sector: sectorsByAsset.get(item.assetId) ?? "UNKNOWN / UNCLASSIFIED" })); });
  }, [scalpQuery.data, swingQuery.data, sectorsByAsset]);
  const filtered = useMemo(() => items.filter(item => {
    const itemRegime = String(item.regime?.classification ?? "UNAVAILABLE").toUpperCase() as RegimeFilter;
    return (status === "ALL" || item.status === status) && (strategy === "ALL" || item.strategy === strategy) && (direction === "ALL" || item.direction === direction) && (regime === "ALL" || itemRegime === regime) && (health === "ALL" || healthFor(item) === health) && (timeframe === "ALL" || timeframeFor(item) === timeframe);
  }), [items, status, strategy, direction, regime, health, timeframe]);
  const publicLoading = scalpQuery.isLoading || swingQuery.isLoading;
  const publicError = scalpQuery.error?.message ?? swingQuery.error?.message;
  const totalAssets = new Set(items.map(item => item.assetId)).size;
  const totalEvaluated = scalpQuery.data || swingQuery.data ? items.length : null;
  const currentRegime = (swingQuery.data as DiscoveryResponse | undefined)?.marketRegime ?? (scalpQuery.data as DiscoveryResponse | undefined)?.marketRegime ?? null;
  const trials = useMemo(() => ((historyQuery.data ?? []) as unknown as Trial[]).toSorted((left, right) => new Date(right.createdAt).getTime() - new Date(left.createdAt).getTime()), [historyQuery.data]);
  const activeTrials = trials.filter(trial => !isTerminal(trial));
  const completedTrials = trials.filter(isTerminal);
  const performance = performanceQuery.data as PerformancePayload | undefined;
  const eligibility = eligibilityQuery.data as EligibilityPayload | undefined;
  const funnel = useMemo(() => {
    const candidateCount = items.filter(item => item.status !== "DATA UNAVAILABLE").length;
    return [
      { label: "ALL ASSETS / EVALUATIONS", count: totalEvaluated },
      { label: "CANDIDATES", count: totalEvaluated == null ? null : candidateCount },
      { label: "WATCH", count: totalEvaluated == null ? null : items.filter(item => item.status === "WATCH").length },
      { label: "POTENTIAL", count: totalEvaluated == null ? null : items.filter(item => item.status === "POTENTIAL").length },
      { label: "QUALIFIED", count: totalEvaluated == null ? null : items.filter(item => item.status === "QUALIFIED").length },
      { label: "AUTO PAPER ELIGIBLE", count: privateEnabled ? eligibility?.eligibleCount ?? null : null },
      { label: "ACTIVE TRIALS", count: privateEnabled ? (eligibility ? activeTrials.length : null) : null },
      { label: "COMPLETED TRIALS", count: privateEnabled ? (eligibility ? completedTrials.length : null) : null },
    ];
  }, [items, totalEvaluated, privateEnabled, eligibility?.eligibleCount, eligibilityQuery.isLoading, activeTrials.length, completedTrials.length]);
  const conversion = useMemo(() => {
    const candidate = funnel[1].count; const watch = funnel[2].count; const potential = funnel[3].count; const qualified = funnel[4].count;
    const rate = (value: number | null, base: number | null) => value == null || base == null || base <= 0 ? "INSUFFICIENT DATA" : `${(value / base * 100).toFixed(1)}%`;
    return [{ label: "Candidate → Potential", value: rate(potential, candidate) }, { label: "Potential → Qualified", value: rate(qualified, potential) }, { label: "Qualified → Auto Paper", value: privateEnabled && eligibility?.eligibleCount != null ? rate(eligibility.eligibleCount, qualified) : "INSUFFICIENT DATA" }, { label: "Auto Paper → Completed", value: privateEnabled && eligibility?.eligibleCount != null ? rate(completedTrials.length, eligibility.eligibleCount) : "INSUFFICIENT DATA" }];
  }, [funnel, privateEnabled, trials.length, completedTrials.length, eligibility?.eligibleCount]);
  const rejectionReasons = useMemo(() => {
    const counts = new Map<string, number>();
    for (const item of items.filter(candidate => candidate.status === "NO TRADE" || candidate.status === "WATCH")) {
      const reasons = [item.exactReason, ...(item.adaptive?.warnings ?? []), ...(item.missingEvidence ?? [])].filter(Boolean) as string[];
      for (const reason of reasons.slice(0, 3)) counts.set(reason, (counts.get(reason) ?? 0) + 1);
    }
    return Array.from(counts.entries()).sort((left, right) => right[1] - left[1]).slice(0, 6).map(([reason, count]) => ({ reason, count }));
  }, [items]);
  const observations = useMemo(() => {
    const notes: string[] = [];
    const potential = funnel[3].count; const candidate = funnel[1].count;
    if (potential != null && candidate != null && candidate > 0) notes.push(`Potential currently represents ${(potential / candidate * 100).toFixed(1)}% of current candidate evaluations.`);
    if (!trials.length) notes.push("Auto Paper comparison is inconclusive until persisted simulation trials exist.");
    else if (activeTrials.length > completedTrials.length) notes.push("Active trials currently outnumber completed trials; outcome comparison is still developing.");
    else if (performance?.sampleLabel) notes.push(`The private Auto Paper sample is labelled ${performance.sampleLabel.toLowerCase()} by the existing server summary.`);
    if (!notes.length) notes.push("Current server-derived evidence does not support a directional experiment observation.");
    return notes;
  }, [funnel, trials.length, activeTrials.length, completedTrials.length, performance?.sampleLabel]);
  const strategyRows = serverRows(performance, "byStrategy", value => value === "SCALP" ? "15M FAST SCALP" : value);
  const timeframeRows = serverRows(performance, "byTimeframe", value => value.toUpperCase());
  const directionRows = serverRows(performance, "byDirection", value => value.toUpperCase());
  const statusRows = [...[qualifiedQuery, potentialQuery, watchQuery].map((query, index) => { const payload = query.data as PerformancePayload | undefined; return { label: ["QUALIFIED", "POTENTIAL", "WATCH"][index], trials: Number(payload?.totalTrials ?? 0), active: Number(payload?.active ?? 0), completed: Number(payload?.completed ?? 0), wins: Number((payload as any)?.wins ?? 0), losses: Number((payload as any)?.losses ?? 0), pnl: Number((payload as any)?.netPnl ?? 0), winRate: (payload as any)?.winRate == null ? null : Number((payload as any).winRate), averageR: (payload as any)?.averageR == null ? null : Number((payload as any).averageR), sampleQuality: sampleQuality(Number(payload?.completed ?? 0)) }; }).filter(Boolean) as CompareRow[]];
  const regimeRows = [riskOnQuery, neutralQuery, riskOffQuery].map((query, index) => { const payload = query.data as PerformancePayload | undefined; return { label: ["RISK ON", "NEUTRAL", "RISK OFF"][index], trials: Number(payload?.totalTrials ?? 0), active: Number(payload?.active ?? 0), completed: Number(payload?.completed ?? 0), wins: Number((payload as any)?.wins ?? 0), losses: Number((payload as any)?.losses ?? 0), pnl: Number((payload as any)?.netPnl ?? 0), winRate: (payload as any)?.winRate == null ? null : Number((payload as any).winRate), averageR: (payload as any)?.averageR == null ? null : Number((payload as any).averageR), sampleQuality: sampleQuality(Number(payload?.completed ?? 0)) }; });
  const coverageRows = (((coverageQuery.data as any)?.rows ?? []) as CoverageRow[]);
  const coverageFrames = useMemo(() => ["15m", "1h", "4h", "1d"].map(frame => { const scopes = coverageRows.map(row => row.timeframes?.[frame]).filter(Boolean) as Array<NonNullable<CoverageRow["timeframes"]>[string]>; const expected = scopes.reduce((sum, scope) => sum + Number(scope.expected ?? 0), 0); const observed = scopes.reduce((sum, scope) => sum + Number(scope.observed ?? 0), 0); return { frame: frame.toUpperCase(), expected, observed, coverage: expected ? observed / expected * 100 : null, quality: scopes.length ? scopes.map(scope => scope.qualityRating).filter(Boolean).sort()[0] ?? "UNAVAILABLE" : "UNAVAILABLE" }; }), [coverageRows]);
  const sectorRows = useMemo(() => { const map = new Map<string, { assets: Set<string>; setups: number; qualified: number; potential: number; watch: number }>(); for (const item of items) { const existing = map.get(item.sector) ?? { assets: new Set<string>(), setups: 0, qualified: 0, potential: 0, watch: 0 }; existing.assets.add(item.assetId); existing.setups += 1; if (item.status === "QUALIFIED") existing.qualified += 1; if (item.status === "POTENTIAL") existing.potential += 1; if (item.status === "WATCH") existing.watch += 1; map.set(item.sector, existing); } return Array.from(map.entries()).sort((left, right) => right[1].setups - left[1].setups); }, [items]);
  const journal = useMemo(() => trials.filter(trial => (journalStrategy === "ALL" || trial.strategy === journalStrategy) && (journalTimeframe === "ALL" || trial.timeframe.toUpperCase() === journalTimeframe) && (journalStatus === "ALL" || trial.status === journalStatus) && (journalDirection === "ALL" || trial.direction.toUpperCase() === journalDirection) && (journalRegime === "ALL" || regimeFor(trial) === journalRegime) && (journalResult === "ALL" || resultFor(trial) === journalResult)), [trials, journalStrategy, journalTimeframe, journalStatus, journalDirection, journalRegime, journalResult]);
  const journalRows = useMemo(() => journal.map(trial => { const current = snapshotObject(trial.currentSnapshot); const targets = [trial.target1, trial.target2, trial.target3]; const plan = snapshotObject(trial.immutablePlanSnapshot); return { "Trial ID": trial.id, Asset: trial.assetId, Strategy: trial.strategy === "SCALP" ? "15M FAST SCALP" : trial.strategy, Timeframe: trial.timeframe, Direction: trial.direction.toUpperCase(), Status: trial.status, Entry: trial.entryPrice ?? "UNAVAILABLE", Stop: trial.stopPrice ?? "UNAVAILABLE", TP1: targets[0] ?? "UNAVAILABLE", TP2: targets[1] ?? "UNAVAILABLE", TP3: targets[2] ?? "UNAVAILABLE", Exit: isTerminal(trial) ? current.price ?? "UNAVAILABLE" : "UNAVAILABLE", Result: resultFor(trial), R: trialR(trial) ?? "UNAVAILABLE", "P&L": trialPnl(trial), Health: current.status ?? trial.status, Regime: regimeFor(trial), "Created At": trial.createdAt, "Completed At": trial.completedAt ?? "UNAVAILABLE", Provider: trial.provider ?? "UNAVAILABLE", Freshness: trial.freshness ?? "UNAVAILABLE", "Data Quality": plan.dataBundle?.coherent === false ? "INCOHERENT" : plan.dataBundle ? "SERVER BUNDLE" : "UNAVAILABLE", Provenance: safeJson(trial.provenance ?? plan.dataBundle) }; }), [journal]);
  const presetRows = useMemo(() => {
    const presets = [{ id: "A", label: "QUALIFIED ONLY", purpose: "Measures strict setup quality.", rows: trials.filter(trial => qualificationFor(trial) === "QUALIFIED") }, { id: "B", label: "QUALIFIED + POTENTIAL", purpose: "Tests whether Potential setups add value.", rows: trials.filter(trial => ["QUALIFIED", "POTENTIAL"].includes(qualificationFor(trial))) }, { id: "C", label: "15M FAST SCALP", purpose: "Measures fast 15M scalp behavior.", rows: trials.filter(trial => trial.strategy === "SCALP") }, { id: "D", label: "SWING", purpose: "Measures swing behavior.", rows: trials.filter(trial => trial.strategy === "SWING") }]; return presets.map(preset => { const groups = groupTrials(preset.rows, trial => preset.id); const group = groups[0]; return { ...preset, status: !preset.rows.length ? "NOT STARTED" : group && group.completed < 5 ? "INSUFFICIENT SAMPLE" : group && group.active ? "RUNNING" : "COMPLETED", trials: group?.trials ?? 0, completed: group?.completed ?? 0, winRate: group?.winRate ?? null, averageR: group?.averageR ?? null, pnl: group?.pnl ?? null, sampleQuality: group?.sampleQuality ?? "NO DATA" }; });
  }, [trials]);
  const exportJournal = (format: "csv" | "json") => { if (!privateEnabled || !journalRows.length) return; const payload = format === "csv" ? toCsv(journalRows) : JSON.stringify({ exportedAt: new Date().toISOString(), accountContext: "AUTO_PAPER_OWNER_SCOPED", filters: { strategy: journalStrategy, timeframe: journalTimeframe, status: journalStatus, direction: journalDirection, regime: journalRegime, result: journalResult }, dataProvenance: "Authenticated Auto Paper history", trials: journalRows }, null, 2); downloadText(`auto-paper-journal-${new Date().toISOString().slice(0, 10)}.${format}`, payload, format === "csv" ? "text/csv" : "application/json"); };
  const exportFunnel = (format: "csv" | "json") => { if (!privateEnabled || totalEvaluated == null) return; const payload = { exportedAt: new Date().toISOString(), totalAssets, totalEvaluations: totalEvaluated, stages: funnel, conversions: conversion, rejectionReasons, dataQuality: { publicError: publicError ?? null, currentRegime: currentRegime?.classification ?? "UNAVAILABLE", coverageDatasetId: datasetId || null }, provenance: "Server-returned discovery and owner-scoped Auto Paper history" }; downloadText(`trading-intelligence-funnel-${new Date().toISOString().slice(0, 10)}.${format}`, format === "csv" ? toCsv([{ ...payload, stages: safeJson(funnel), conversions: safeJson(conversion), rejectionReasons: safeJson(rejectionReasons), dataQuality: safeJson(payload.dataQuality) }]) : JSON.stringify(payload, null, 2), format === "csv" ? "text/csv" : "application/json"); };

  return <section className="min-h-screen rounded-2xl border border-white/[.08] bg-[#080e19]/95 p-4 shadow-2xl sm:p-6">
    <header className="flex flex-wrap items-start justify-between gap-4 border-b border-white/[.07] pb-5"><div className="flex items-start gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-cyan-300/[.12] text-cyan-200"><Radar className="h-5 w-5" /></span><div><p className="text-[10px] font-semibold uppercase tracking-[.18em] text-cyan-300">Trading Intelligence · read only</p><h1 className="mt-1 text-xl font-semibold tracking-tight text-slate-100">Analytics and experiment command center</h1><p className="mt-2 max-w-3xl text-xs leading-5 text-slate-400">Measure the current strategy without changing it. Every opportunity state, performance metric, coverage badge, and journal row is server-derived; no screen open creates a trial or snapshot.</p></div></div><Button variant="outline" onClick={onBack} className="border-white/[.1] bg-white/[.025] text-slate-200"><ArrowLeft className="mr-2 h-4 w-4" />Back to Dashboard</Button></header>
    {!online ? <div role="status" className="mt-5 rounded-xl border border-amber-300/25 bg-amber-300/[.06] p-4 text-xs text-amber-100"><strong>OFFLINE · READ ONLY.</strong> Current opportunities and private analytics require a fresh server response.</div> : null}
    {currentRegime?.classification === "RISK OFF" ? <div className="mt-5 flex gap-3 rounded-xl border border-rose-300/25 bg-rose-300/[.06] p-4 text-xs text-rose-100"><ShieldAlert className="h-4 w-4 shrink-0" /><p><strong>RISK OFF.</strong> Potential and Watch setups remain visible below with a regime warning. This workspace does not weaken qualification or create Paper actions.</p></div> : null}

    <section className="mt-5 rounded-2xl border border-cyan-300/15 bg-cyan-300/[.025] p-4"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-[10px] font-semibold uppercase tracking-[.16em] text-cyan-300">Top summary</p><h2 className="mt-1 text-sm font-semibold text-slate-100">Current server-returned universe</h2></div><span className="text-[11px] text-slate-500">{totalEvaluated == null ? "Awaiting server response" : `${totalEvaluated} strategy evaluations · ${totalAssets} unique assets`}</span></div><div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-7"><Metric label="Total assets" value={totalEvaluated == null ? "—" : totalAssets} /><Metric label="Candidates" value={funnel[1].count == null ? "—" : funnel[1].count} /><Metric label="Qualified" value={funnel[4].count == null ? "—" : funnel[4].count} /><Metric label="Potential" value={funnel[3].count == null ? "—" : funnel[3].count} /><Metric label="Watch" value={funnel[2].count == null ? "—" : funnel[2].count} /><Metric label="No trade" value={totalEvaluated == null ? "—" : items.filter(item => item.status === "NO TRADE").length} /><Metric label="Data unavailable" value={totalEvaluated == null ? "—" : items.filter(item => item.status === "DATA UNAVAILABLE").length} /></div></section>

    <section className="mt-5 rounded-2xl border border-cyan-300/15 bg-cyan-300/[.025] p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-[10px] font-semibold uppercase tracking-[.16em] text-cyan-300">Opportunity funnel</p><h2 className="mt-1 text-sm font-semibold text-slate-100">Where the current universe lands</h2></div><div className="flex gap-2"><Button size="sm" variant="outline" disabled={!privateEnabled || totalEvaluated == null} onClick={() => exportFunnel("csv")} aria-label="Export funnel CSV" className="border-white/[.1] bg-white/[.025] text-xs text-slate-200"><Download className="mr-1.5 h-3.5 w-3.5" />Export Funnel CSV</Button><Button size="sm" variant="outline" disabled={!privateEnabled || totalEvaluated == null} onClick={() => exportFunnel("json")} aria-label="Export funnel JSON" className="border-white/[.1] bg-white/[.025] text-xs text-slate-200"><Download className="mr-1.5 h-3.5 w-3.5" />JSON</Button></div></div><div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-8">{funnel.map((item, index) => <div key={item.label} className="rounded-lg border border-white/[.07] bg-white/[.025] p-3"><div className="flex min-h-10 items-start justify-between gap-2"><span className="text-[9px] font-semibold uppercase tracking-[.1em] text-slate-500">{item.label}</span><strong className="font-mono text-lg text-slate-100">{item.count == null ? "—" : item.count}</strong></div>{index > 0 ? <p className="mt-2 text-[10px] text-slate-500">{item.count == null || funnel[index - 1].count == null || Number(funnel[index - 1].count) <= 0 ? "INSUFFICIENT DATA" : `${(Number(item.count) / Number(funnel[index - 1].count) * 100).toFixed(1)}% of prior`}</p> : <p className="mt-2 text-[10px] text-slate-500">Server response</p>}</div>)}</div><div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">{conversion.map(item => <div key={item.label} className="rounded-lg border border-white/[.07] bg-black/10 p-3"><p className="text-[9px] font-semibold uppercase tracking-[.1em] text-slate-500">{item.label}</p><p className="mt-1 font-mono text-sm text-cyan-200">{item.value}</p></div>)}</div><p className="mt-3 text-[11px] text-slate-500">Auto Paper stages are private and show observed persisted trials only. Empty private stages are labelled INSUFFICIENT DATA or NOT STARTED rather than being represented as performance.</p></section>

    <section className="mt-5 rounded-xl border border-white/[.07] bg-white/[.018] p-4"><div className="flex items-center gap-2"><Filter className="h-4 w-4 text-cyan-300" /><p className="text-[10px] font-semibold uppercase tracking-[.16em] text-cyan-300">Adaptive display filters</p><span className="text-[10px] text-slate-500">presentation only</span></div><div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6"><SelectField label="Status" value={status} options={["ALL", ...STATUS_ORDER]} onChange={value => setStatus(value as StatusFilter)} /><SelectField label="Strategy" value={strategy} options={["ALL", "SCALP", "SWING"]} onChange={value => setStrategy(value as StrategyFilter)} /><SelectField label="Direction" value={direction} options={["ALL", "LONG", "SHORT"]} onChange={value => setDirection(value as DirectionFilter)} /><SelectField label="Regime" value={regime} options={["ALL", "RISK ON", "SELECTIVE", "NEUTRAL", "RISK OFF", "UNAVAILABLE"]} onChange={value => setRegime(value as RegimeFilter)} /><SelectField label="Health" value={health} options={["ALL", "HEALTHY", "WARNING", "REVERSAL RISK", "INVALIDATED", "UNKNOWN"]} onChange={value => setHealth(value as HealthFilter)} /><SelectField label="Timeframe" value={timeframe} options={["ALL", "15M", "1H", "4H", "1D"]} onChange={value => setTimeframe(value as TimeframeFilter)} /></div><p className="mt-3 text-[11px] text-slate-500">Showing {filtered.length} of {totalEvaluated ?? "—"} server-returned evaluations. Filters do not recalculate scores or change eligibility.</p></section>

    <section className="mt-5 grid gap-3 xl:grid-cols-2"><section className="rounded-xl border border-amber-300/15 bg-amber-300/[.025] p-4"><div className="flex items-center gap-2"><CircleAlert className="h-4 w-4 text-amber-300" /><p className="text-[10px] font-semibold uppercase tracking-[.16em] text-amber-200">Key observations</p></div><div className="mt-3 space-y-2">{observations.map(note => <p key={note} className="rounded-lg border border-white/[.07] bg-black/10 p-3 text-xs leading-5 text-slate-300">{note}</p>)}</div><p className="mt-3 text-[11px] text-slate-500">Observations describe measured evidence only. They are not trade recommendations.</p></section><section className="rounded-xl border border-rose-300/15 bg-rose-300/[.025] p-4"><p className="text-[10px] font-semibold uppercase tracking-[.16em] text-rose-200">Top server rejection reasons</p>{rejectionReasons.length ? <div className="mt-3 space-y-2">{rejectionReasons.map(item => <div key={item.reason} className="flex items-start justify-between gap-3 rounded-lg border border-white/[.07] bg-black/10 p-3 text-xs"><span className="line-clamp-2 text-slate-300">{item.reason}</span><strong className="shrink-0 font-mono text-rose-200">{item.count}</strong></div>)}</div> : <p className="mt-3 text-xs text-slate-500">NO DATA · No server rejection evidence is available.</p>}</section></section>

    <section className="mt-5 space-y-3">{publicLoading ? <EmptyBlock text="Loading current server-validated opportunities…" /> : publicError ? <EmptyBlock text={`DATA UNAVAILABLE · ${publicError}`} /> : filtered.length ? filtered.slice(0, 24).map(item => <OpportunityIntelligenceRow key={`${item.strategy}-${item.assetId}`} item={item} onInspectAsset={onInspectAsset} />) : <EmptyBlock text={totalEvaluated == null ? "DATA UNAVAILABLE · No validated opportunity response is available." : "NO MATCHES · The selected presentation filters do not match the current server response."} />}</section>

    <section className="mt-6 rounded-2xl border border-violet-300/15 bg-violet-300/[.025] p-4"><div><p className="text-[10px] font-semibold uppercase tracking-[.16em] text-violet-200">Experiment Lab</p><h2 className="mt-1 text-sm font-semibold text-slate-100">A vs B vs C vs D · observed Auto Paper evidence</h2><p className="mt-2 text-xs leading-5 text-slate-400">Preset comparisons use existing private trial history only. A preset that has not been observed is labelled NOT STARTED, not zero.</p></div><div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">{presetRows.map(preset => <article key={preset.id} className="rounded-xl border border-white/[.07] bg-black/10 p-3"><div className="flex items-start justify-between gap-2"><div><p className="text-[10px] font-semibold uppercase tracking-[.12em] text-violet-200">MODE {preset.id}</p><h3 className="mt-1 text-xs font-semibold text-slate-100">{preset.label}</h3></div><Badge variant="outline" className="border-violet-300/25 text-[9px] text-violet-200">{isAuthenticated ? preset.status : "OWNER ONLY"}</Badge></div><p className="mt-3 text-[11px] leading-4 text-slate-400">{preset.purpose}</p><div className="mt-3 grid grid-cols-2 gap-2 text-[10px]"><span className="text-slate-500">Trials <strong className="ml-1 font-mono text-slate-200">{isAuthenticated && preset.trials ? preset.trials : isAuthenticated ? "NOT STARTED" : "OWNER ONLY"}</strong></span><span className="text-slate-500">Completed <strong className="ml-1 font-mono text-slate-200">{isAuthenticated && preset.completed ? preset.completed : isAuthenticated ? "NOT STARTED" : "OWNER ONLY"}</strong></span><span className="text-slate-500">Win rate <strong className="ml-1 font-mono text-cyan-200">{preset.winRate == null ? preset.sampleQuality : `${preset.winRate.toFixed(1)}%`}</strong></span><span className="text-slate-500">Average R <strong className="ml-1 font-mono text-cyan-200">{preset.averageR == null ? preset.sampleQuality : number(preset.averageR)}</strong></span><span className="text-slate-500">P/L <strong className="ml-1 font-mono text-slate-200">{preset.pnl == null ? preset.sampleQuality : money.format(preset.pnl)}</strong></span><span className="text-slate-500">Sample <strong className="ml-1 text-violet-200">{preset.sampleQuality}</strong></span></div><p className="mt-3 rounded-lg border border-white/[.06] p-2 text-[10px] leading-4 text-slate-500">Includes: {preset.label}. Excludes other presets. Eligibility remains governed by existing server settings.</p></article>)}</div><div className="mt-4 flex justify-end"><Button size="sm" variant="outline" onClick={onOpenAutoPaper} className="border-violet-300/25 bg-violet-300/[.05] text-violet-100"><Sparkles className="mr-1.5 h-3.5 w-3.5" />Open Auto Paper Lab</Button></div></section>

    <section className="mt-6 rounded-2xl border border-emerald-300/15 bg-emerald-300/[.025] p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-[10px] font-semibold uppercase tracking-[.16em] text-emerald-300">Performance comparisons</p><h2 className="mt-1 text-sm font-semibold text-slate-100">Strategy, timeframe, status, direction, regime</h2><p className="mt-2 text-xs leading-5 text-slate-400">Metrics below are read from the owner-scoped Auto Paper performance procedures. A small sample stays labelled and is not declared a winner.</p></div><div className="grid grid-cols-2 gap-2 text-right text-[10px] text-slate-500 sm:grid-cols-4"><Metric label="Trials" value={!isAuthenticated ? "OWNER ONLY" : performance?.totalTrials ?? "NOT STARTED"} /><Metric label="Completed" value={!isAuthenticated ? "OWNER ONLY" : performance?.completed ?? "NOT STARTED"} /><Metric label="Net P/L" value={!isAuthenticated || performance?.netPnl == null ? (!isAuthenticated ? "OWNER ONLY" : "NO DATA") : money.format(performance.netPnl)} /><Metric label="Max drawdown" value={!isAuthenticated || performance?.maximumDrawdown == null ? (!isAuthenticated ? "OWNER ONLY" : "NO DATA") : money.format(performance.maximumDrawdown)} /></div></div>{!isAuthenticated ? <div className="mt-4 flex gap-3 rounded-lg border border-amber-300/20 bg-amber-300/[.05] p-3 text-xs text-amber-100"><LockKeyhole className="h-4 w-4 shrink-0" /><p>Owner authentication is required for private trials, accounting, comparison metrics, and journal rows. Public opportunity states remain read-only.</p></div> : <div className="mt-4 grid gap-3 xl:grid-cols-2"><Comparison title="Strategy · Scalp vs Swing" rows={strategyRows} loading={performanceQuery.isLoading} /><Comparison title="Timeframe · 15M / 1H / 4H / 1D" rows={timeframeRows} loading={performanceQuery.isLoading} /><Comparison title="Status · Qualified vs Potential vs Watch" rows={statusRows} loading={qualifiedQuery.isLoading || potentialQuery.isLoading || watchQuery.isLoading} /><Comparison title="Direction · Long vs Short" rows={directionRows} loading={performanceQuery.isLoading} /><Comparison title="Regime · Risk On / Neutral / Risk Off" rows={regimeRows} loading={riskOnQuery.isLoading || neutralQuery.isLoading || riskOffQuery.isLoading} /></div>}</section>

    <section className="mt-6 rounded-2xl border border-sky-300/15 bg-sky-300/[.025] p-4"><div><p className="text-[10px] font-semibold uppercase tracking-[.16em] text-sky-200">Sector comparison</p><h2 className="mt-1 text-sm font-semibold text-slate-100">Current server universe composition</h2><p className="mt-2 text-xs leading-5 text-slate-400">Current sector/category labels are displayed only when returned by the server. Historical sector performance is not inferred from asset names and remains unavailable when reliable point-in-time sector context is absent.</p></div>{sectorRows.length ? <div className="mt-4 overflow-x-auto"><table className="w-full min-w-[720px] text-left text-xs"><thead className="text-[9px] uppercase tracking-[.14em] text-slate-500"><tr><th className="px-3 py-2">Sector</th><th className="px-3 py-2">Assets</th><th className="px-3 py-2">Setups</th><th className="px-3 py-2">Qualified</th><th className="px-3 py-2">Potential</th><th className="px-3 py-2">Trials</th><th className="px-3 py-2">Win rate</th><th className="px-3 py-2">Sample quality</th></tr></thead><tbody>{sectorRows.map(([sector, row]) => <tr key={sector} className="border-t border-white/[.06]"><td className="px-3 py-3 font-semibold text-slate-200">{sector}</td><td className="px-3 py-3 font-mono text-slate-300">{row.assets.size}</td><td className="px-3 py-3 font-mono text-slate-300">{row.setups}</td><td className="px-3 py-3 font-mono text-emerald-200">{row.qualified}</td><td className="px-3 py-3 font-mono text-amber-200">{row.potential}</td><td className="px-3 py-3 text-slate-500">UNAVAILABLE</td><td className="px-3 py-3 text-slate-500">UNAVAILABLE</td><td className="px-3 py-3 text-slate-500">NO HISTORICAL SECTOR SAMPLE</td></tr>)}</tbody></table></div> : <EmptyBlock text="SECTOR DATA UNAVAILABLE · No server-returned sector/category labels are available." />}</section>

    <section className="mt-6 rounded-2xl border border-white/[.07] bg-white/[.018] p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-[10px] font-semibold uppercase tracking-[.16em] text-cyan-300">Historical coverage</p><h2 className="mt-1 text-sm font-semibold text-slate-100">Dataset-backed evidence readiness</h2><p className="mt-2 text-xs leading-5 text-slate-400">Coverage badges describe retained historical OHLCV quality only. They do not change Opportunity Score or create historical performance samples.</p></div><Badge variant="outline" className="border-cyan-300/25 text-cyan-200">{isAuthenticated && datasetId ? `DATASET ${datasetId}` : "OWNER / DATASET"}</Badge></div>{!isAuthenticated ? <EmptyBlock text="OWNER AUTHENTICATION REQUIRED · Historical coverage is protected." /> : coverageQuery.isLoading || datasetsQuery.isLoading ? <EmptyBlock text="Loading historical coverage…" /> : coverageRows.length ? <div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{coverageFrames.map(frame => <div key={frame.frame} className="rounded-lg border border-white/[.07] bg-black/10 p-3"><div className="flex items-center justify-between"><span className="text-[10px] font-semibold uppercase tracking-[.12em] text-slate-500">{frame.frame}</span><SampleBadge label={frame.quality} /></div><p className="mt-3 font-mono text-lg text-cyan-200">{frame.coverage == null ? "NO DATA" : `${frame.coverage.toFixed(1)}%`}</p><p className="mt-1 text-[10px] text-slate-500">Observed {frame.observed.toLocaleString()} / expected {frame.expected.toLocaleString()} candles</p></div>)}</div> : <EmptyBlock text="NO DATA · No sealed historical coverage dataset is available for this owner." />}</section>

    <section className="mt-6 rounded-2xl border border-white/[.07] bg-white/[.018] p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><BookOpen className="h-4 w-4 text-cyan-300" /><div><p className="text-[10px] font-semibold uppercase tracking-[.16em] text-cyan-300">Trading Journal</p><h2 className="mt-1 text-sm font-semibold text-slate-100">Chronological Auto Paper record</h2></div></div><div className="flex gap-2"><Button size="sm" variant="outline" disabled={!privateEnabled || !journalRows.length} onClick={() => exportJournal("csv")} aria-label="Export journal CSV" className="border-white/[.1] bg-white/[.025] text-xs text-slate-200"><Download className="mr-1.5 h-3.5 w-3.5" />Export CSV</Button><Button size="sm" variant="outline" disabled={!privateEnabled || !journalRows.length} onClick={() => exportJournal("json")} aria-label="Export journal JSON" className="border-white/[.1] bg-white/[.025] text-xs text-slate-200"><Download className="mr-1.5 h-3.5 w-3.5" />Export JSON</Button></div></div>{!isAuthenticated ? <EmptyBlock text="OWNER AUTHENTICATION REQUIRED · Private Auto Paper journal is not public." /> : <><div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6"><SelectField label="Strategy" value={journalStrategy} options={["ALL", "SCALP", "SWING"]} onChange={setJournalStrategy} /><SelectField label="Timeframe" value={journalTimeframe} options={["ALL", "15M", "1H", "4H", "1D"]} onChange={setJournalTimeframe} /><SelectField label="Status" value={journalStatus} options={["ALL", ...Array.from(new Set(trials.map(trial => trial.status))).sort()]} onChange={setJournalStatus} /><SelectField label="Direction" value={journalDirection} options={["ALL", "LONG", "SHORT"]} onChange={setJournalDirection} /><SelectField label="Regime" value={journalRegime} options={["ALL", "RISK ON", "NEUTRAL", "RISK OFF", "UNAVAILABLE"]} onChange={setJournalRegime} /><SelectField label="Result" value={journalResult} options={["ALL", "ACTIVE", "WIN", "LOSS", "BREAKEVEN"]} onChange={setJournalResult} /></div><div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><Metric label="Total" value={trials.length || "NOT STARTED"} /><Metric label="Active" value={trials.length ? activeTrials.length : "NOT STARTED"} /><Metric label="Completed" value={trials.length ? completedTrials.length : "NOT STARTED"} /><Metric label="Wins" value={trials.length ? completedTrials.filter(trial => Number(trial.realizedPnl ?? 0) > 0).length : "NOT STARTED"} /><Metric label="Losses" value={trials.length ? completedTrials.filter(trial => Number(trial.realizedPnl ?? 0) < 0).length : "NOT STARTED"} /><Metric label="Invalidated" value={trials.length ? trials.filter(trial => trial.status === "INVALIDATED").length : "NOT STARTED"} /><Metric label="Data unavailable" value={trials.length ? trials.filter(trial => trial.status === "DATA_UNAVAILABLE").length : "NOT STARTED"} /><Metric label="Win rate" value={performance?.winRate == null ? (trials.length ? sampleQuality(completedTrials.length) : "NOT STARTED") : `${Number((performance as any).winRate).toFixed(1)}%`} /></div>{journal.length ? <div className="mt-3 overflow-x-auto"><table className="w-full min-w-[900px] text-left text-xs"><thead className="text-[9px] uppercase tracking-[.14em] text-slate-500"><tr><th className="px-3 py-2">Time</th><th className="px-3 py-2">Asset / strategy</th><th className="px-3 py-2">Direction</th><th className="px-3 py-2">Status</th><th className="px-3 py-2">P/L</th><th className="px-3 py-2">Qualification / regime</th></tr></thead><tbody>{journal.slice(0, 24).map(trial => <tr key={trial.id} className="border-t border-white/[.06]"><td className="px-3 py-3 text-slate-500">{date(trial.completedAt ?? trial.createdAt)}</td><td className="px-3 py-3"><strong className="text-slate-200">{trial.assetId}</strong><span className="ml-2 text-slate-500">{trial.strategy === "SCALP" ? "15M FAST SCALP" : trial.strategy} · {trial.timeframe}</span></td><td className="px-3 py-3 text-slate-300">{trial.direction.toUpperCase()}</td><td className="px-3 py-3"><Badge variant="outline" className={trial.status === "COMPLETED" || trial.status.includes("TARGET") ? "border-emerald-300/25 text-emerald-200" : trial.status === "STOPPED" || trial.status === "INVALIDATED" ? "border-rose-300/25 text-rose-200" : "border-amber-300/25 text-amber-200"}>{trial.status.replaceAll("_", " ")}</Badge></td><td className={trialPnl(trial) >= 0 ? "px-3 py-3 font-mono text-emerald-200" : "px-3 py-3 font-mono text-rose-200"}>{money.format(trialPnl(trial))}</td><td className="px-3 py-3 text-slate-500">{qualificationFor(trial)} · {regimeFor(trial)}</td></tr>)}</tbody></table></div> : <EmptyBlock text={historyQuery.isLoading ? "Loading private Auto Paper history…" : "NOT STARTED · No persisted Auto Paper trials match the current filters."} />}</>}</section>

    <div className="mt-5 flex flex-wrap items-center gap-2 text-[11px] text-slate-500"><BarChart3 className="h-4 w-4 text-cyan-300" />All prices, plans, lifecycle states, performance, coverage, and exports remain server-derived. This workspace never sends exchange orders and never mixes Manual Paper accounting with Auto Paper.</div>
  </section>;
}

function SelectField({ label, value, options, onChange }: { label: string; value: string; options: string[]; onChange: (value: string) => void }) {
  return <label className="flex min-w-0 flex-col gap-1 text-[10px] font-semibold uppercase tracking-[.12em] text-slate-500"><span>{label}</span><select aria-label={label} value={value} onChange={event => onChange(event.target.value)} className="h-9 w-full rounded-lg border border-white/[.08] bg-[#0b1321] px-2 text-[11px] font-normal tracking-normal text-slate-200 outline-none focus:border-cyan-300/40">{options.map(option => <option key={option} value={option}>{option === "ALL" ? "All" : option}</option>)}</select></label>;
}

function OpportunityIntelligenceRow({ item, onInspectAsset }: { item: WorkspaceItem; onInspectAsset?: (assetId: string) => void }) {
  const plan = item.sourcePlan;
  const hasPlan = Boolean(plan?.entryZone && plan.stop && plan.targets?.length);
  const statusTone = item.status === "QUALIFIED" ? "border-emerald-300/25 bg-emerald-300/[.07] text-emerald-200" : item.status === "POTENTIAL" ? "border-amber-300/25 bg-amber-300/[.07] text-amber-200" : item.status === "WATCH" ? "border-cyan-300/25 bg-cyan-300/[.07] text-cyan-200" : item.status === "NO TRADE" ? "border-rose-300/25 bg-rose-300/[.07] text-rose-200" : "border-slate-300/20 bg-slate-300/[.05] text-slate-300";
  return <article className="rounded-xl border border-white/[.07] bg-white/[.02] p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div className="flex min-w-0 items-start gap-3"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-slate-800 font-mono text-xs font-bold text-cyan-200">{item.symbol.slice(0, 2)}</span><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h3 className="text-sm font-semibold text-slate-100">{item.symbol}</h3><Badge variant="outline" className={statusTone}>{item.status}</Badge><Badge variant="outline" className="border-white/[.08] text-slate-400">{item.strategy === "SCALP" ? "15M FAST SCALP" : "SWING"}</Badge><Badge variant="outline" className="border-white/[.08] text-slate-400">{item.direction}</Badge><Badge variant="outline" className="border-white/[.08] text-slate-400">{item.sector}</Badge>{item.regime?.restricted ? <Badge variant="outline" className="border-rose-300/25 text-rose-200">RISK OFF</Badge> : null}</div><p className="mt-1 text-[11px] text-slate-500">Opportunity {item.opportunityScore ?? "UNAVAILABLE"}/100 · Quality {item.adaptive?.quality?.score ?? "UNAVAILABLE"} · Confidence {item.adaptive?.quality?.confidence ?? "UNAVAILABLE"} · {item.provider ?? "UNAVAILABLE"} · {date(item.dataTimestamp)}</p></div></div><div className="text-right"><p className="text-[9px] font-semibold uppercase tracking-[.14em] text-slate-500">Readiness</p><p className="mt-1 font-mono text-lg text-cyan-200">{item.setupReadiness?.score ?? "—"}</p></div></div><div className="mt-3 grid gap-3 border-t border-white/[.06] pt-3 md:grid-cols-[1.2fr_.8fr] md:items-start"><div><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-cyan-300">WHY / STATUS</p><p className="mt-1 text-xs leading-5 text-slate-300">{item.exactReason ?? "Server explanation unavailable."}</p>{item.regime?.restricted ? <p className="mt-2 flex items-center gap-1.5 text-[11px] text-rose-200"><CircleAlert className="h-3.5 w-3.5" />Setup exists, but market regime is unfavorable. Qualification remains restricted.</p> : null}<p className="mt-2 text-[11px] text-slate-500">Health: {healthFor(item)} · Trade readiness: {item.tradeReadiness ?? "UNAVAILABLE"} · Timeframe: {timeframeFor(item)} · Sector: {item.sector}</p></div><div className="rounded-lg border border-white/[.06] bg-black/10 p-3 text-[11px] text-slate-400">{hasPlan ? <><p className="font-semibold uppercase tracking-[.12em] text-slate-500">Validated plan levels</p><div className="mt-2 grid grid-cols-2 gap-2"><span>Entry <strong className="font-mono text-slate-200">{number(plan?.entryZone?.preferred)}</strong></span><span>Stop <strong className="font-mono text-rose-200">{number(plan?.stop?.price)}</strong></span>{plan?.targets.slice(0, 3).map(target => <span key={target.label}>{target.label} <strong className="font-mono text-emerald-200">{number(target.price)}</strong></span>)}<span>R:R <strong className="font-mono text-cyan-200">{number(plan?.rewardRisk)}</strong></span></div></> : <><p className="font-semibold uppercase tracking-[.12em] text-amber-200">TRADE PLAN UNAVAILABLE</p><p className="mt-1 leading-4">No complete server-derived Entry / Stop / Target path is available for this status.</p></>}</div></div>{onInspectAsset ? <button type="button" onClick={() => onInspectAsset(item.assetId)} className="mt-3 w-full rounded-lg border border-cyan-300/20 bg-cyan-300/[.04] px-3 py-2 text-left text-[10px] font-semibold uppercase tracking-[.14em] text-cyan-200 transition-colors hover:bg-cyan-300/[.08] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-300/70">Open Asset Detail Workspace →</button> : null}</article>;
}

function Comparison({ title, rows, loading = false }: { title: string; rows: CompareRow[]; loading?: boolean }) {
  return <section className="rounded-xl border border-white/[.07] bg-white/[.02] p-3"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-cyan-300">{title}</p>{loading ? <p className="mt-3 text-[11px] text-slate-500">Loading server performance…</p> : rows.length ? <div className="mt-3 space-y-3">{rows.map(row => <div key={row.label}><div className="flex items-center justify-between gap-2 text-xs"><strong className="truncate text-slate-200">{row.label}</strong><span className="font-mono text-slate-500">{row.trials || "NO DATA"}</span></div><div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-slate-800"><div className="h-full rounded-full bg-emerald-300" style={{ width: `${row.trials ? Math.min(100, Number(row.completed) / Number(row.trials) * 100) : 0}%` }} /></div><p className="mt-1 text-[10px] text-slate-500">Completed {row.completed || "NO DATA"} · Wins {row.completed ? row.wins : "NO DATA"} · Win rate {row.winRate == null ? row.sampleQuality ?? "INSUFFICIENT DATA" : `${row.winRate.toFixed(1)}%`} · Avg R {row.averageR == null ? row.sampleQuality ?? "INSUFFICIENT DATA" : number(row.averageR)} · P/L {row.trials ? money.format(row.pnl) : "NO DATA"}</p><p className="mt-1 text-[9px] uppercase tracking-[.12em] text-violet-200">Sample badge · {row.sampleQuality ?? sampleQuality(row.completed)}</p></div>)}</div> : <p className="mt-3 text-[11px] leading-4 text-slate-500">NO DATA · No persisted Auto Paper observations in this comparison.</p>}</section>;
}
function Metric({ label, value }: { label: string; value: string | number }) { return <div className="rounded-lg border border-white/[.07] bg-white/[.025] p-3"><p className="text-[9px] font-semibold uppercase tracking-[.13em] text-slate-500">{label}</p><p className="mt-1 truncate font-mono text-sm text-slate-100">{value}</p></div>; }
function SampleBadge({ label }: { label: string }) { return <span className="rounded-full border border-violet-300/25 bg-violet-300/[.06] px-2 py-1 text-[9px] font-semibold uppercase tracking-[.1em] text-violet-200">{label}</span>; }
function EmptyBlock({ text }: { text: string }) { return <div className="grid place-items-center rounded-xl border border-dashed border-white/[.09] bg-white/[.015] p-8 text-center text-xs text-slate-500"><CircleAlert className="h-5 w-5 text-slate-600" /><p className="mt-2">{text}</p></div>; }
